"use client";

import * as React from "react";
import { DayPicker } from "react-day-picker";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { PixelButton } from "./button";

function PixelCalendar({
  className, classNames, showOutsideDays = true, ...props
}: React.ComponentProps<typeof DayPicker>) {
  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn("p-3 font-[family-name:var(--pixel-font)]", className)}
      classNames={{
        months: "flex flex-col sm:flex-row gap-4",
        month: "flex flex-col gap-4",
        caption: "flex justify-center pt-1 relative items-center",
        caption_label: "text-xs uppercase tracking-widest",
        nav: "flex items-center gap-1",
        nav_button: cn("h-7 w-7 bg-transparent p-0 opacity-50 hover:opacity-100 border-2 border-foreground inline-flex items-center justify-center"),
        nav_button_previous: "absolute left-1",
        nav_button_next: "absolute right-1",
        table: "w-full border-collapse space-y-1",
        head_row: "flex",
        head_cell: "text-muted-foreground w-8 font-normal text-[10px] uppercase",
        row: "flex w-full mt-2",
        cell: "h-8 w-8 text-center text-xs p-0 relative [&:has([aria-selected].day-range-end)]:rounded-none [&:has([aria-selected].day-outside)]:bg-accent/50 [&:has([aria-selected])]:bg-accent first:[&:has([aria-selected])]:rounded-none last:[&:has([aria-selected])]:rounded-none focus-within:relative focus-within:z-20",
        day: cn("h-8 w-8 p-0 font-normal aria-selected:opacity-100 border-2 border-transparent hover:border-foreground"),
        day_range_end: "day-range-end",
        day_selected: "bg-primary text-primary-foreground border-2 border-foreground hover:bg-primary hover:text-primary-foreground focus:bg-primary focus:text-primary-foreground",
        day_today: "border-2 border-accent font-bold",
        day_outside: "day-outside text-muted-foreground opacity-50 aria-selected:bg-accent/50 aria-selected:text-muted-foreground aria-selected:opacity-30",
        day_disabled: "text-muted-foreground opacity-50",
        day_range_middle: "aria-selected:bg-accent aria-selected:text-accent-foreground",
        day_hidden: "invisible",
        ...classNames,
      }}
      components={{
        IconLeft: () => <ChevronLeft className="h-4 w-4" strokeWidth={3} />,
        IconRight: () => <ChevronRight className="h-4 w-4" strokeWidth={3} />,
      }}
      {...props}
    />
  );
}
PixelCalendar.displayName = "PixelCalendar";

export { PixelCalendar };
